    private fun chapter1() = StoryChapter(
        number = 1, title = "The Apollonian and the Dionysian", titlePersian = "آپولونی و دیونیزوسی",
        paragraphs = listOf(
            StoryParagraph("In the ancient world of Greece, there were two gods who ruled over the human spirit, two brothers who were also opposites, two forces that together created the greatest art the world has ever known.", "در جهان کهن یونان، دو خدا بر روح انسانی حکومت می‌کردند، دو برادر که همزمان متضاد یکدیگر بودند، دو نیرو که با هم بزرگ‌ترین هنری را آفریدند که جهان تا به حال شناخته است."),
            StoryParagraph("The first was Apollo, god of light and reason, god of dreams and images, god of the beautiful illusion that makes life bearable, god of the calm surface that hides the terrible depths below.", "نخستین آپولون بود، خدای نور و خرد، خدای رؤیاها و تصاویر، خدای توهم زیبایی که زندگی را قابل تحمل می‌کند، خدای سطح آرامی که عمق‌های هولناک زیرین را پنهان می‌کند."),
            StoryParagraph("The second was Dionysus, god of wine and ecstasy, god of music and dance, god of the terrifying truth that lies beneath all illusions, god of the wild chaos that shatters every boundary.", "دومین دیونیزوس بود، خدای شراب و سرخوشی، خدای موسیقی و رقص، خدای حقیقت هولناکی که زیر تمام توهمات جای دارد، خدای آشوب وحشی که هر مرزی را می‌شکند."),
            StoryParagraph("Apollo was the god of the individual, the god of the separate self, the god of the clear line that divides one thing from another, the god of the beautiful form that gives shape to chaos.", "آپولون خدای فرد بود، خدای خود جداگانه، خدای خط روشنی که یک چیز را از دیگری جدا می‌کند، خدای شکل زیبایی که به آشوب شکل می‌دهد."),
            StoryParagraph("Dionysus was the god of the collective, the god of the dissolved self, the god of the blurred line that unites all things, the god of the formless ecstasy that dissolves all boundaries.", "دیونیزوس خدای جمع بود، خدای خود حل‌شده، خدای خط محوی که همه چیز را یکی می‌کند، خدای سرخوشی بی‌شکل که تمام مرزها را حل می‌کند."),
            StoryParagraph("Apollo was the god of the dream, the god of the image, the god of the beautiful appearance that we mistake for reality, the god of the veil that covers the truth.", "آپولون خدای رؤیا بود، خدای تصویر، خدای ظاهر زیبایی که آن را با واقعیت اشتباه می‌گیریم، خدای حجابی که حقیقت را می‌پوشاند."),
            StoryParagraph("Dionysus was the god of intoxication, the god of the music, the god of the terrifying reality that lies behind the veil, the god of the truth that shatters all illusions.", "دیونیزوس خدای مستی بود، خدای موسیقی، خدای واقعیت هولناکی که پشت حجاب جای دارد، خدای حقیقتی که تمام توهمات را می‌شکند."),
            StoryParagraph("And the Greeks, who were the wisest of all peoples, understood that both gods were necessary, understood that neither could exist without the other, understood that the greatest art came from the marriage of the two.", "و یونانیان، که خردمندترین مردمان بودند، می‌فهمیدند هر دو خدا لازمند، می‌فهمیدند هیچ‌کدام بدون دیگری نمی‌تواند وجود داشته باشد، می‌فهمیدند بزرگ‌ترین هنر از ازدواج آن دو زاده می‌شود."),
            StoryParagraph("For the Apollonian without the Dionysian is empty, is cold, is a beautiful surface with nothing beneath, is a dream from which we never wake, is a lie we tell ourselves to avoid the truth.", "زیرا آپولونی بدون دیونیزوسی تهی است، سرد است، سطحی زیباست که هیچ چیز زیرش نیست، رؤیایی است که هرگز از آن بیدار نمی‌شویم، دروغی است که به خودمان می‌گوییم تا از حقیقت بگریزیم."),
            StoryParagraph("And the Dionysian without the Apollonian is unbearable, is chaotic, is a formless void that swallows everything, is a truth so terrible that it destroys those who see it, is a reality that no human being can endure.", "و دیونیزوسی بدون آپولونی غیرقابل تحمل است، آشوبناک است، تهی بی‌شکلی است که همه چیز را می‌بلعد، حقیقتی است چنان هولناک که بینندگانش را نابود می‌کند، واقعیتی است که هیچ انسانی نمی‌تواند تحملش کند."),
            StoryParagraph("The Apollonian says: life is beautiful, life has meaning, life is worth living. The Dionysian says: life is terrible, life is meaningless, life is suffering without end. And both, somehow, are true.", "آپولونی می‌گوید: زندگی زیباست، زندگی معنا دارد، زندگی ارزش زیستن دارد. دیونیزوسی می‌گوید: زندگی هولناک است، زندگی بی‌معناست، زندگی رنجی بی‌پایان است. و هر دو، به شکلی، درستند."),
            StoryParagraph("The Greeks understood this, understood the terror of existence, understood that to live was to suffer, understood that the world was cruel and indifferent and meaningless. And yet they did not despair.", "یونانیان این را می‌فهمیدند، وحشت وجود را می‌فهمیدند، می‌فهمیدند زندگی کردن یعنی رنج کشیدن، می‌فهمیدند جهان بی‌رحم و بی‌تفاوت و بی‌معناست. و با این حال ناامید نشدند."),
            StoryParagraph("Instead, they created tragedy, created the greatest art form the world has ever known, created a form that could hold both the Apollonian and the Dionysian, a form that could face the truth and still affirm life.", "در عوض، تراژدی آفریدند، بزرگ‌ترین شکل هنری را که جهان تا به حال شناخته است آفریدند، شکلی آفریدند که می‌توانست هم آپولونی و هم دیونیزوسی را در خود داشته باشد، شکلی که می‌توانست با حقیقت روبرو شود و با این حال زندگی را تأیید کند."),
            StoryParagraph("For tragedy is not pessimism, not resignation, not despair. Tragedy is the affirmation of life in the face of its terror. Tragedy is the yes that is spoken even when the answer is no.", "زیرا تراژدی بدبینی نیست، تسلیم نیست، ناامیدی نیست. تراژدی تأیید زندگی در برابر وحشت آن است. تراژدی آری‌ای است که حتی وقتی پاسخ نه است گفته می‌شود."),
            StoryParagraph("The tragic hero does not escape his fate, does not flee from suffering, does not pretend that the world is other than it is. The tragic hero faces his fate, embraces his suffering, and in doing so, becomes something more than human.", "قهرمان تراژیک از سرنوشتش نمی‌گریزد، از رنج فرار نمی‌کند، تظاهر نمی‌کند جهان جز آنچه هست است. قهرمان تراژیک با سرنوشتش روبرو می‌شود، رنجش را در آغوش می‌گیرد، و در این کار، به چیزی بیشتر از انسان تبدیل می‌شود."),
            StoryParagraph("This, Nietzsche said, is the wisdom of the Greeks, the wisdom that we have lost, the wisdom that we must recover if we are to live fully, if we are to live honestly, if we are to live at all.", "این، نیچه گفت، خرد یونانیان است، خردی که از دست داده‌ایم، خردی که باید بازیابیم اگر می‌خواهیم به تمامی زندگی کنیم، اگر می‌خواهیم صادقانه زندگی کنیم، اگر می‌خواهیم اصلاً زندگی کنیم."),
            StoryParagraph("For we moderns have lost this wisdom, have replaced it with optimism, with the belief that life is good, that progress is inevitable, that suffering can be eliminated, that the world is rational and just.", "زیرا ما مدرن‌ها این خرد را از دست داده‌ایم، آن را با خوش‌بینی جایگزین کرده‌ایم، با باور به اینکه زندگی خوب است، پیشرفت ناگزیر است، رنج می‌تواند حذف شود، جهان عقلانی و عادلانه است."),
            StoryParagraph("But this optimism is a lie, is a shallow lie, is a lie that makes us weak, is a lie that makes us unable to face the truth, is a lie that will eventually destroy us.", "اما این خوش‌بینی دروغ است، دروغی سطحی است، دروغی است که ما را ضعیف می‌کند، دروغی است که ما را ناتوان از رویارویی با حقیقت می‌کند، دروغی است که در نهایت نابودمان می‌کند."),
            StoryParagraph("And so Nietzsche called for a return to the tragic, called for a return to the wisdom of the Greeks, called for a return to the marriage of the Apollonian and the Dionysian, called for a return to the art that could face the truth.", "و اینگونه نیچه خواستار بازگشت به تراژیک شد، خواستار بازگشت به خرد یونانیان شد، خواستار بازگشت به ازدواج آپولونی و دیونیزوسی شد، خواستار بازگشت به هنری شد که می‌توانست با حقیقت روبرو شود."),
            StoryParagraph("For art, he said, is not the enemy of truth but its greatest ally, not the escape from reality but the fullest embrace of it, not the lie that hides reality but the truth that reveals it.", "زیرا هنر، او گفت، دشمن حقیقت نیست بلکه بزرگ‌ترین متحدش است، نه فرار از واقعیت بلکه کامل‌ترین در آغوش گرفتن آن، نه دروغی که واقعیت را پنهان می‌کند بلکه حقیقتی که آن را آشکار می‌کند."),
            StoryParagraph("Art does not deny the terror of existence, does not pretend that suffering is not real, does not cover up the abyss. Art faces the terror, embraces the suffering, gazes into the abyss, and transforms it into something beautiful.", "هنر وحشت وجود را انکار نمی‌کند، تظاهر نمی‌کند رنج واقعی نیست، پرتگاه را نمی‌پوشاند. هنر با وحشت روبرو می‌شود، رنج را در آغوش می‌گیرد، به پرتگاه می‌نگرد، و آن را به چیزی زیبا تبدیل می‌کند."),
            StoryParagraph("This is the power of tragedy, this is the power of art, this is the power of the human spirit, to transform suffering into beauty, to transform terror into affirmation, to transform death into life.", "این قدرت تراژدی است، این قدرت هنر است، این قدرت روح انسانی است، تبدیل رنج به زیبایی، تبدیل وحشت به تأیید، تبدیل مرگ به زندگی."),
            StoryParagraph("And so Nietzsche began his book, began his meditation on the birth of tragedy, began his call for a new understanding of art and life and truth, began his attack on the optimism that he believed was destroying the modern world.", "و اینگونه نیچه کتابش را آغاز کرد، تأملش بر تولد تراژدی را آغاز کرد، دعوتش به فهم نوینی از هنر و زندگی و حقیقت را آغاز کرد، حمله‌اش به خوش‌بینی‌ای را که باور داشت جهان مدرن را نابود می‌کند آغاز کرد."),
            StoryParagraph("The book was not well received, was misunderstood by his contemporaries, was ignored by the scholars of his time, was dismissed by those who should have understood it best.", "کتاب خوب دریافت نشد، توسط همعصرانش بدفهمیده شد، توسط دانشمندان زمانش نادیده گرفته شد، توسط کسانی که باید بهترین درکش می‌کردند رد شد."),
            StoryParagraph("But the book survived, survived its author, survived its time, survived its neglect, and would come to be recognized as one of the greatest works of philosophy ever written.", "اما کتاب زنده ماند، از نویسنده‌اش جان به سلامت برد، از زمانش جان به سلامت برد، از نادیده گرفته شدنش جان به سلامت برد، و به‌عنوان یکی از بزرگ‌ترین آثار فلسفی که تا به حال نوشته شده شناخته می‌شد."),
            StoryParagraph("For in this book, Nietzsche asked the questions that every human being must ask, the questions about the meaning of life, about the value of existence, about the nature of art and truth and suffering.", "زیرا در این کتاب، نیچه پرسش‌هایی را پرسید که هر انسانی باید بپرسد، پرسش‌هایی درباره معنای زندگی، درباره ارزش هستی، درباره ماهیت هنر و حقیقت و رنج."),
            StoryParagraph("And the answers he gave, the answers he suggested, the answers he implied, would shape the course of philosophy for the next century and beyond, would influence thinkers and artists and writers across the world.", "و پاسخ‌هایی که داد، پاسخ‌هایی که پیشنهاد کرد، پاسخ‌هایی که ضمنی گفت، مسیر فلسفه را برای قرن بعدی و فراتر از آن شکل می‌داد، بر متفکران و هنرمندان و نویسندگان سراسر جهان تأثیر می‌گذاشت."),
            StoryParagraph("And so ended the first part of the story of the birth of tragedy, with the introduction of the two gods, with the description of their marriage, with the beginning of a philosophy that would change everything.", "و اینگونه بخش نخست داستان تولد تراژدی با معرفی دو خدا، با توصیف ازدواجشان، با آغاز فلسفه‌ای که همه چیز را تغییر می‌داد، به پایان رسید."),
            StoryParagraph("For tragedy is not merely an art form, not merely a literary genre, not merely a cultural artifact, but a way of being in the world, a way of facing existence, a way of affirming life in the face of its terror.", "زیرا تراژدی تنها یک شکل هنری نیست، تنها یک ژانر ادبی نیست، تنها یک اثر فرهنگی نیست، بلکه شیوه‌ای از بودن در جهان است، شیوه‌ای از رویارویی با هستی، شیوه‌ای از تأیید زندگی در برابر وحشت آن."),
            StoryParagraph("And this way of being, this way of facing, this way of affirming, was what Nietzsche sought to recover, was what he sought to teach, was what he sought to live himself.", "و این شیوه بودن، این شیوه رویارویی، این شیوه تأیید، چیزی بود که نیچه در پی بازیافتنش بود، چیزی بود که در پی آموختنش بود، چیزی بود که خودش در پی زیستنش بود."),
            StoryParagraph("And so the story began, and so the story continued, and so the story would end, with the understanding that tragedy is not the enemy of life but its highest expression.", "و اینگونه داستان آغاز شد و اینگونه ادامه یافت و اینگونه پایان می‌یافت، با این درک که تراژدی دشمن زندگی نیست بلکه والاترین بیان آن است."),
            StoryParagraph("The two gods stood side by side, the god of light and the god of darkness, the god of form and the god of chaos, the god of the dream and the god of intoxication, and between them, in the space they created together, tragedy was born.", "دو خدا کنار هم ایستادند، خدای نور و خدای تاریکی، خدای شکل و خدای آشوب، خدای رؤیا و خدای مستی، و میان آن‌ها، در فضایی که با هم آفریدند، تراژدی زاده شد."),
            StoryParagraph("And the birth of tragedy was the birth of wisdom, was the birth of courage, was the birth of the only way of living that could face the truth and still say yes to life.", "و تولد تراژدی تولد خرد بود، تولد شجاعت بود، تولد تنها شیوه زندگی‌ای بود که می‌توانست با حقیقت روبرو شود و با این حال به زندگی آری بگوید."),
            StoryParagraph("This was Nietzsche's insight, this was his discovery, this was his gift to the world, and he would spend the rest of his life developing it, elaborating it, deepening it, until he could no longer think at all.", "این بصیرت نیچه بود، این کشف او بود، این هدیه‌اش به جهان بود، و باقی عمرش را صرف بسط آن می‌کرد، توضیحش می‌کرد، عمیق‌ترش می‌کرد، تا وقتی که دیگر اصلاً نمی‌توانست بیندیشد."),
            StoryParagraph("And so the first part of the story ended, and the second part began, with the description of the Apollonian art, with the analysis of the dream, with the understanding of the beautiful illusion that makes life possible.", "و اینگونه بخش نخست داستان پایان یافت و بخش دوم آغاز شد، با توصیف هنر آپولونی، با تحلیل رؤیا، با فهم توهم زیبایی که زندگی را ممکن می‌کند."),
            StoryParagraph("For Apollo, Nietzsche said, is the god of the dream, and the dream is the origin of all art, is the origin of all images, is the origin of the beautiful illusion that allows us to live in a world that would otherwise be unbearable.", "زیرا آپولون، نیچه گفت، خدای رؤیاست و رؤیا خاستگاه تمام هنر است، خاستگاه تمام تصاویر است، خاستگاه توهم زیبایی است که به ما اجازه می‌دهد در جهانی زندگی کنیم که در غیر این صورت غیرقابل تحمل می‌بود."),
            StoryParagraph("And so the story continued, as stories must, toward the understanding of the two forces, toward the marriage of the two gods, toward the birth of the art that would save humanity from despair.", "و اینگونه داستان ادامه یافت، همان‌طور که داستان‌ها باید، به سمت فهم دو نیرو، به سمت ازدواج دو خدا، به سمت تولد هنری که بشریت را از ناامیدی نجات می‌داد."),
            StoryParagraph("And so ended the first part of the story of the birth of tragedy, with the stage set, with the players in place, with the birth ready to be described.", "و اینگونه بخش نخست داستان تولد تراژدی با صحنه آماده، با بازیگران در جای خود، با تولدی آماده برای توصیف، به پایان رسید."),
            StoryParagraph("The two gods waited, waited for the philosopher to understand them, waited for the artist to embody them, waited for the tragedy to be born, and their waiting was not in vain.", "دو خدا منتظر ماندند، منتظر ماندند تا فیلسوف درکشان کند، منتظر ماندند تا هنرمند تجسمشان کند، منتظر ماندند تا تراژدی زاده شود، و انتظارشان بیهوده نبود.")
        )
    )

    private fun chapter2() = StoryChapter(
        number = 2, title = "The Apollonian Dream", titlePersian = "رؤیای آپولونی",
        paragraphs = listOf(
            StoryParagraph("Apollo, Nietzsche said, is the god of the dream, and to understand Apollo is to understand the dream, and to understand the dream is to understand the origin of all art.", "آپولون، نیچه گفت، خدای رؤیاست، و فهم آپولون یعنی فهم رؤیا، و فهم رؤیا یعنی فهم خاستگاه تمام هنر."),
            StoryParagraph("Every night, we dream, and in our dreams we see images, and these images are not random but meaningful, are not chaotic but ordered, are not ugly but beautiful, are not meaningless but full of significance.", "هر شب رؤیا می‌بینیم، و در رؤیاهایمان تصاویر می‌بینیم، و این تصاویر تصادفی نیستند بلکه معنادارند، آشوبناک نیستند بلکه مرتب‌اند، زشت نیستند بلکه زیبایند، بی‌معنا نیستند بلکه پر از معنا."),
            StoryParagraph("In the dream, we are not ourselves, or rather we are more than ourselves, for the dream reveals aspects of our being that are hidden in waking life, aspects that we do not know or do not want to know.", "در رؤیا، خودمان نیستیم، یا بهتر، بیشتر از خودمان هستیم، زیرا رؤیا جنبه‌هایی از هستی ما را آشکار می‌کند که در زندگی بیداری پنهانند، جنبه‌هایی که نمی‌دانیم یا نمی‌خواهیم بدانیم."),
            StoryParagraph("The dream is the origin of the image, and the image is the origin of art, for all art is a kind of dream, is a kind of image, is a kind of beautiful illusion that we create and then contemplate.", "رؤیا خاستگاه تصویر است، و تصویر خاستگاه هنر است، زیرا تمام هنر نوعی رؤیاست، نوعی تصویر است، نوعی توهم زیباست که می‌آفرینیم و سپس در آن تأمل می‌کنیم."),
            StoryParagraph("The painter dreams in colors, the sculptor in forms, the poet in words, the musician in sounds, and each of them creates a world that is not the real world, that is more beautiful than the real world, that is more meaningful than the real world.", "نقاش در رنگ‌ها رؤیا می‌بیند، مجسمه‌ساز در فرم‌ها، شاعر در کلمات، موسیقی‌دان در صداها، و هر یک جهانی می‌آفریند که جهان واقعی نیست، زیباتر از جهان واقعی است، معنادارتر از جهان واقعی است."),
            StoryParagraph("But this beauty, this meaning, this world, is an illusion, is a beautiful illusion, is an illusion that we know to be an illusion and yet choose to believe, for without it, life would be unbearable.", "اما این زیبایی، این معنا، این جهان، توهم است، توهم زیباست، توهمی است که می‌دانیم توهم است و با این حال انتخاب می‌کنیم باورش کنیم، زیرا بدونش، زندگی غیرقابل تحمل می‌بود."),
            StoryParagraph("This is the wisdom of Apollo, the wisdom of the dream, the wisdom of the image, the wisdom that says: yes, the world is terrible, but we can make it beautiful, yes, life is meaningless, but we can give it meaning, yes, existence is chaos, but we can give it form.", "این خرد آپولون است، خرد رؤیا، خرد تصویر، خردی که می‌گوید: آری، جهان هولناک است، اما می‌توانیم زیبایش کنیم، آری، زندگی بی‌معناست، اما می‌توانیم به آن معنا بدهیم، آری، هستی آشوب است، اما می‌توانیم به آن شکل بدهیم."),
            StoryParagraph("And this is what the Greeks did, what they did better than any other people, what they did so well that we still admire them, still study them, still try to imitate them.", "و این همان کاری است که یونانیان کردند، همان کاری که بهتر از هر مردم دیگری کردند، همان کاری که چنان خوب کردند که هنوز تحسینشان می‌کنیم، هنوز مطالعه‌شان می‌کنیم، هنوز تلاش می‌کنیم از آنان تقلید کنیم."),
            StoryParagraph("They took the chaos of existence and gave it form, took the terror of life and gave it beauty, took the meaningless of the world and gave it meaning, and they did this through art, through myth, through the beautiful illusion.", "آن‌ها آشوب هستی را گرفتند و به آن شکل دادند، وحشت زندگی را گرفتند و به آن زیبایی دادند، بی‌معنایی جهان را گرفتند و به آن معنا دادند، و این کار را از طریق هنر کردند، از طریق اسطوره، از طریق توهم زیبا."),
            StoryParagraph("The gods of Olympus, Nietzsche said, are not a religion but an art, are not a belief but a dream, are not a truth but a beautiful illusion that the Greeks created to make life bearable.", "خدایان المپ، نیچه گفت، دین نیستند بلکه هنرند، باور نیستند بلکه رؤیایند، حقیقت نیستند بلکه توهم زیبایی هستند که یونانیان برای قابل تحمل کردن زندگی آفریدند."),
            StoryParagraph("The gods of Olympus are beautiful, are strong, are happy, are everything that human beings are not, are everything that human beings wish to be, and in contemplating them, the Greeks could forget, for a moment, the terror of their own existence.", "خدایان المپ زیبایند، نیرومندند، خوشحالند، هر چیزی هستند که انسان‌ها نیستند، هر چیزی هستند که انسان‌ها آرزو می‌کنند باشند، و در تأمل بر آن‌ها، یونانیان می‌توانستند برای لحظه‌ای وحشت هستی خودشان را فراموش کنند."),
            StoryParagraph("The Apollonian is the veil that covers the abyss, is the light that hides the darkness, is the form that conceals the chaos, is the dream that makes life possible.", "آپولونی حجابی است که پرتگاه را می‌پوشاند، نوری است که تاریکی را پنهان می‌کند، شکلی است که آشوب را پنهان می‌کند، رؤیایی است که زندگی را ممکن می‌کند."),
            StoryParagraph("But the Apollonian is not the whole truth, is not the final word, is not the ultimate wisdom, for there is something that the Apollonian cannot reach, something that the Apollonian cannot express, something that the Apollonian cannot contain.", "اما آپولونی تمام حقیقت نیست، سخن نهایی نیست، خرد نهایی نیست، زیرا چیزی هست که آپولونی نمی‌تواند به آن برسد، چیزی که آپولونی نمی‌تواند بیان کند، چیزی که آپولونی نمی‌تواند در خود داشته باشد."),
            StoryParagraph("And that something is the Dionysian, is the intoxication, is the music, is the terrifying truth that lies behind the beautiful veil, is the abyss that the veil conceals.", "و آن چیز دیونیزوسی است، مستی است، موسیقی است، حقیقت هولناکی است که پشت حجاب زیبا جای دارد، پرتگاهی است که حجاب پنهانش می‌کند."),
            StoryParagraph("The Apollonian alone is not enough, for it is too beautiful, is too serene, is too calm, is too distant from the realities of human existence, is too much of a dream.", "آپولونی به تنهایی کافی نیست، زیرا بیش از حد زیباست، بیش از حد آرام، بیش از حد ساکن، بیش از حد از واقعیت‌های هستی انسانی دور، بیش از حد رؤیا."),
            StoryParagraph("The Apollonian alone would lead to an art that is beautiful but hollow, that is pleasant but meaningless, that is pleasing but untrue, that is a lie we tell ourselves to avoid the truth.", "آپولونی به تنهایی به هنری می‌رسید که زیباست اما توخالی، خوشایند اما بی‌معنا، مطبوع اما نادرست، دروغی است که به خودمان می‌گوییم تا از حقیقت بگریزیم."),
            StoryParagraph("And this is what Nietzsche feared, this is what he saw in the modern world, this is what he believed was destroying art and life alike: an excess of the Apollonian, an excess of the dream, an excess of the beautiful illusion.", "و این چیزی بود که نیچه از آن می‌ترسید، این چیزی بود که در جهان مدرن می‌دید، این چیزی بود که باور داشت هنر و زندگی را همزمان نابود می‌کند: زیاده‌روی در آپولونی، زیاده‌روی در رؤیا، زیاده‌روی در توهم زیبا."),
            StoryParagraph("The modern world, he said, has forgotten the Dionysian, has forgotten the music, has forgotten the intoxication, has forgotten the terrifying truth that the Greeks never forgot, and in forgetting these things, it has become weak, has become shallow, has become unable to face reality.", "جهان مدرن، او گفت، دیونیزوسی را فراموش کرده، موسیقی را فراموش کرده، مستی را فراموش کرده، حقیقت هولناکی را فراموش کرده که یونانیان هرگز فراموش نکردند، و در فراموش کردن این چیزها، ضعیف شده، سطحی شده، ناتوان از رویارویی با واقعیت شده."),
            StoryParagraph("And so Nietzsche called for a return to the Dionysian, called for a return to the music, called for a return to the intoxication, called for a return to the terrifying truth that the modern world had abandoned.", "و اینگونه نیچه خواستار بازگشت به دیونیزوسی شد، خواستار بازگشت به موسیقی شد، خواستار بازگشت به مستی شد، خواستار بازگشت به حقیقت هولناکی شد که جهان مدرن رهایش کرده بود."),
            StoryParagraph("For only by returning to the Dionysian, he said, could we recover the wisdom of the Greeks, could we recover the power of tragedy, could we recover the art that faces the truth and still affirms life.", "زیرا تنها با بازگشت به دیونیزوسی، او گفت، می‌توانستیم خرد یونانیان را بازیابیم، می‌توانستیم قدرت تراژدی را بازیابیم، می‌توانستیم هنری را بازیابیم که با حقیقت روبرو می‌شود و با این حال زندگی را تأیید می‌کند."),
            StoryParagraph("And so ended the second part of the story of the birth of tragedy, with the description of the Apollonian, with the analysis of the dream, with the call for the return to the Dionysian.", "و اینگونه بخش دوم داستان تولد تراژدی با توصیف آپولونی، با تحلیل رؤیا، با دعوت به بازگشت به دیونیزوسی، به پایان رسید."),
            StoryParagraph("For the Apollonian was not enough, would never be enough, could never be enough, for it was only half of the truth, only half of art, only half of life.", "زیرا آپولونی کافی نبود، هرگز کافی نمی‌شد، هرگز نمی‌توانست کافی باشد، زیرا تنها نیمی از حقیقت بود، تنها نیمی از هنر، تنها نیمی از زندگی."),
            StoryParagraph("And so the second part ended, and the third part began, with the description of the Dionysian, with the analysis of music, with the understanding of the intoxication that shatters all boundaries.", "و اینگونه بخش دوم پایان یافت و بخش سوم آغاز شد، با توصیف دیونیزوسی، با تحلیل موسیقی، با فهم مستی‌ای که تمام مرزها را می‌شکند."),
            StoryParagraph("For the Dionysian was the other half, was the half that had been forgotten, was the half that the modern world had rejected, was the half that was necessary for the whole.", "زیرا دیونیزوسی نیمه دیگر بود، نیمه‌ای بود که فراموش شده بود، نیمه‌ای بود که جهان مدرن ردش کرده بود، نیمه‌ای بود که برای کل لازم بود."),
            StoryParagraph("And so the story continued, as stories must, toward the marriage of the two forces, toward the birth of tragedy, toward the wisdom that had been lost and that Nietzsche sought to recover.", "و اینگونه داستان ادامه یافت، همان‌طور که داستان‌ها باید، به سمت ازدواج دو نیرو، به سمت تولد تراژدی، به سمت خردی که از دست رفته بود و نیچه در پی بازیافتنش بود."),
            StoryParagraph("And so ended the second part of the story of the birth of tragedy, with the Apollonian described, with the Dionysian anticipated, with the marriage that would create tragedy still to come.", "و اینگونه بخش دوم داستان تولد تراژدی با آپولونی توصیف شده، با دیونیزوسی انتظار کشیده شده، با ازدواجی که تراژدی می‌آفرید هنوز در راه، به پایان رسید."),
            StoryParagraph("And so the second part ended, and the third began, and the story moved toward its climax, and the birth of tragedy approached, and nothing could stop it.", "و اینگونه بخش دوم پایان یافت و سوم آغاز شد و داستان به سمت اوجش حرکت کرد و تولد تراژدی نزدیک شد و هیچ چیز نمی‌توانست متوقفش کند."),
            StoryParagraph("The two gods waited, waited for the marriage, waited for the birth, waited for the philosopher to understand what they had always known: that only together could they create something that neither could create alone.", "دو خدا منتظر ماندند، منتظر ازدواج ماندند، منتظر تولد ماندند، منتظر ماندند تا فیلسوف آنچه را که همیشه می‌دانستند بفهمد: که تنها با هم می‌توانستند چیزی بیافرینند که هیچ‌کدام به تنهایی نمی‌توانست."),
            StoryParagraph("And so the second part of the story of the birth of tragedy ended, with the Apollonian understood, with the Dionysian anticipated, with the marriage of the two forces still to be described.", "و اینگونه بخش دوم داستان تولد تراژدی با آپولونی فهمیده شده، با دیونیزوسی انتظار کشیده شده، با ازدواج دو نیرو هنوز برای توصیف، به پایان رسید."),
            StoryParagraph("The dream was beautiful, but it was only a dream. The music was coming, and the music would wake us from the dream, and in waking, we would see the truth, and the truth would set us free.", "رؤیا زیبا بود، اما تنها رؤیا بود. موسیقی می‌آمد و موسیقی ما را از رؤیا بیدار می‌کرد و در بیداری حقیقت را می‌دیدیم و حقیقت ما را آزاد می‌کرد.")
        )
    )

    private fun chapter3() = StoryChapter(
        number = 3, title = "The Dionysian Music", titlePersian = "موسیقی دیونیزوسی",
        paragraphs = listOf(
            StoryParagraph("Dionysus, Nietzsche said, is the god of music, and to understand Dionysus is to understand music, and to understand music is to understand the deepest truth of human existence.", "دیونیزوس، نیچه گفت، خدای موسیقی است، و فهم دیونیزوس یعنی فهم موسیقی، و فهم موسیقی یعنی فهم عمیق‌ترین حقیقت وجود انسانی."),
            StoryParagraph("Music is not like the other arts, not like painting, not like sculpture, not like poetry. Music does not represent, does not imitate, does not copy. Music is the thing itself, is the will itself, is the reality itself.", "موسیقی مثل هنرهای دیگر نیست، مثل نقاشی نیست، مثل مجسمه‌سازی نیست، مثل شعر نیست. موسیقی نمایندگی نمی‌کند، تقلید نمی‌کند، کپی نمی‌کند. موسیقی خودِ چیز است، خودِ اراده است، خودِ واقعیت است."),
            StoryParagraph("When we listen to music, we do not see images, we do not hear words, we do not think thoughts. We feel something, something deeper than images and words and thoughts, something that cannot be expressed in any other way.", "هنگامی که به موسیقی گوش می‌دهیم، تصاویر نمی‌بینیم، کلمات نمی‌شنویم، اندیشه‌ها نمی‌اندیشیم. چیزی حس می‌کنیم، چیزی عمیق‌تر از تصاویر و کلمات و اندیشه‌ها، چیزی که به هیچ شکل دیگری نمی‌توان بیان کرد."),
            StoryParagraph("And what we feel is the terror of existence, the terror that all Apollonian illusions conceal, the terror that all beautiful images hide, the terror that all reasonable thoughts deny.", "و آنچه حس می‌کنیم وحشت وجود است، وحشتی که تمام توهمات آپولونی پنهانش می‌کنند، وحشتی که تمام تصاویر زیبا مخفی‌اش می‌کنند، وحشتی که تمام اندیشه‌های معقول انکارش می‌کنند."),
            StoryParagraph("But we also feel something else, something that is not terror but is its opposite, something that is joy but is not the joy of the Apollonian, something that is affirmation but is not the affirmation of the dream.", "اما چیز دیگری هم حس می‌کنیم، چیزی که وحشت نیست بلکه متضادش است، چیزی که شادی است اما شادی آپولونی نیست، چیزی که تأیید است اما تأیید رؤیا نیست."),
            StoryParagraph("This is the Dionysian joy, the joy that comes from the dissolution of the self, the joy that comes from the merging with the whole, the joy that comes from the recognition that we are not separate but one.", "این شادی دیونیزوسی است، شادی‌ای که از حل شدن خود می‌آید، شادی‌ای که از ادغام با کل می‌آید، شادی‌ای که از تشخیص اینکه جدا نیستیم بلکه یکی هستیم می‌آید."),
            StoryParagraph("In the Dionysian state, we lose ourselves, we forget who we are, we forget where we are, we forget what we believe, we forget all the boundaries that Apollo has drawn, and in forgetting, we become something more.", "در حالت دیونیزوسی، خود را از دست می‌دهیم، فراموش می‌کنیم کی هستیم، فراموش می‌کنیم کجا هستیم، فراموش می‌کنیم به چه باور داریم، تمام مرزهایی که آپولون کشیده فراموش می‌کنیم، و در فراموش کردن، چیزی بیشتر می‌شویم."),
            StoryParagraph("This is what happens in the ecstasy of the dance, in the frenzy of the celebration, in the intoxication of the wine. We are no longer ourselves, no longer individuals, no longer separate. We are one with the god, one with the crowd, one with the world.", "این همان چیزی است که در سرخوشی رقص اتفاق می‌افتد، در جنون جشن، در مستی شراب. دیگر خودمان نیستیم، دیگر افراد نیستیم، دیگر جدا نیستیم. با خدا یکی هستیم، با جمع یکی هستیم، با جهان یکی هستیم."),
            StoryParagraph("And this unity, this merging, this dissolution, is terrifying and joyful at the same time, is destructive and creative at the same time, is death and rebirth at the same time.", "و این یگانگی، این ادغام، این حل شدن، همزمان هولناک و شادی‌آور است، همزمان ویرانگر و آفریننده است، همزمان مرگ و تولد دوباره است."),
            StoryParagraph("For when the individual dissolves, something dies, but something else is born, something that cannot be born as long as the individual remains, something that can only come into being when the boundaries are crossed.", "زیرا وقتی فرد حل می‌شود، چیزی می‌میرد، اما چیز دیگری زاده می‌شود، چیزی که نمی‌تواند زاده شود تا زمانی که فرد باقی است، چیزی که تنها زمانی می‌تواند به هستی بیاید که مرزها عبور شوند."),
            StoryParagraph("This is the Dionysian, this is the music, this is the intoxication, this is the terrifying and beautiful truth that lies at the heart of human existence, the truth that we are not separate but one, not individuals but parts of a greater whole.", "این دیونیزوسی است، این موسیقی است، این مستی است، این حقیقت هولناک و زیبایی است که در قلب وجود انسانی جای دارد، حقیقتی که جدا نیستیم بلکه یکی هستیم، افراد نیستیم بلکه بخش‌هایی از کل بزرگ‌تری هستیم."),
            StoryParagraph("The Apollonian speaks to us as individuals, as separate selves, as distinct beings. The Dionysian speaks to us as members of a tribe, as parts of a whole, as drops in an ocean.", "آپولونی با ما به‌عنوان افراد صحبت می‌کند، به‌عنوان خودهای جداگانه، به‌عنوان موجودات متمایز. دیونیزوسی با ما به‌عنوان اعضای قبیله صحبت می‌کند، به‌عنوان بخش‌هایی از یک کل، به‌عنوان قطره‌هایی در اقیانوس."),
            StoryParagraph("And both are true, both are necessary, both are part of what it means to be human. We are individuals, yes, but we are also more than individuals. We are separate, yes, but we are also one.", "و هر دو درستند، هر دو لازمند، هر دو بخشی از معنای انسان بودنند. ما افرادیم، آری، اما بیشتر از افراد هم هستیم. ما جداییم، آری، اما یکی هم هستیم."),
            StoryParagraph("The wisdom of tragedy, Nietzsche said, is the wisdom that holds both truths at once, that affirms both the individual and the whole, that sees both the Apollonian and the Dionysian as necessary parts of a greater whole.", "خرد تراژدی، نیچه گفت، خردی است که هر دو حقیقت را همزمان نگه می‌دارد، هم فرد و هم کل را تأیید می‌کند، هم آپولونی و هم دیونیزوسی را به‌عنوان بخش‌های لازم کل بزرگ‌تری می‌بیند."),
            StoryParagraph("For tragedy is not the triumph of the Dionysian over the Apollonian, is not the destruction of the individual by the whole, is not the drowning of the self in the ocean of being.", "زیرا تراژدی پیروزی دیونیزوسی بر آپولونی نیست، نابودی فرد توسط کل نیست، غرق شدن خود در اقیانوس هستی نیست."),
            StoryParagraph("Tragedy is the marriage of the two, is the dance between the two, is the eternal tension between the two, is the creative conflict that gives birth to the greatest art.", "تراژدی ازدواج آن دو است، رقص میان آن دو است، تنش ابدی بین آن دو است، تعارض آفریننده‌ای است که بزرگ‌ترین هنر را می‌زاید."),
            StoryParagraph("The tragic hero is an individual, an Apollonian figure, a person with a name and a story and a fate. And yet, in his suffering, in his death, in his destruction, he becomes something more, becomes a symbol, becomes a representation of the human condition.", "قهرمان تراژیک فردی است، چهره‌ای آپولونی، شخصی با نام و داستان و سرنوشت. و با این حال، در رنجش، در مرگش، در نابودی‌اش، به چیزی بیشتر تبدیل می‌شود، به نمادی، به نمایندگی از وضعیت بشری."),
            StoryParagraph("And the audience, watching the tragedy, experiences both the Apollonian joy of the beautiful form and the Dionysian joy of the dissolved self. They weep, and their weeping is beautiful. They are destroyed, and their destruction is sublime.", "و تماشاگران، با تماشای تراژدی، هم شادی آپولونی شکل زیبا و هم شادی دیونیزوسی خود حل‌شده را تجربه می‌کنند. گریه می‌کنند و گریه‌شان زیباست. نابود می‌شوند و نابودی‌شان والاست."),
            StoryParagraph("This is the power of tragedy, this is the power of art, this is the power of the marriage of the two gods, and it is this power that Nietzsche sought to recover, to celebrate, to teach.", "این قدرت تراژدی است، این قدرت هنر است، این قدرت ازدواج دو خداست، و این قدرتی است که نیچه در پی بازیافتنش بود، جشن گرفتنش، آموختنش."),
            StoryParagraph("For the modern world, he said, has lost this power, has lost this wisdom, has lost this art. It has become too Apollonian, too rational, too optimistic, too beautiful, too shallow.", "زیرا جهان مدرن، او گفت، این قدرت را از دست داده، این خرد را از دست داده، این هنر را از دست داده. بیش از حد آپولونی شده، بیش از حد عقلانی، بیش از حد خوش‌بین، بیش از حد زیبا، بیش از حد سطحی."),
            StoryParagraph("And so Nietzsche called for a return to the Dionysian, called for a return to the music, called for a return to the tragic, called for a return to the art that could face the truth and still affirm life.", "و اینگونه نیچه خواستار بازگشت به دیونیزوسی شد، خواستار بازگشت به موسیقی شد، خواستار بازگشت به تراژیک شد، خواستار بازگشت به هنری شد که می‌توانست با حقیقت روبرو شود و با این حال زندگی را تأیید کند."),
            StoryParagraph("And he found this return in the music of Wagner, in the operas that Wagner was writing, in the art that Wagner was creating, in the man who would become his greatest friend and then his greatest enemy.", "و این بازگشت را در موسیقی واگنر یافت، در اپراهایی که واگنر می‌نوشت، در هنری که واگنر می‌آفرید، در مردی که بزرگ‌ترین دوستش و سپس بزرگ‌ترین دشمنش می‌شد."),
            StoryParagraph("For Wagner, Nietzsche believed, had recovered the Dionysian, had brought music back to its original power, had created a new form of tragedy that could speak to the modern world.", "زیرا واگنر، نیچه باور داشت، دیونیزوسی را بازیافته بود، موسیقی را به قدرت اصلی‌اش بازگردانده بود، شکل جدیدی از تراژدی آفریده بود که می‌توانست با جهان مدرن سخن بگوید."),
            StoryParagraph("And so ended the third part of the story of the birth of tragedy, with the description of the Dionysian, with the analysis of music, with the hope that the modern world could recover the wisdom it had lost.", "و اینگونه بخش سوم داستان تولد تراژدی با توصیف دیونیزوسی، با تحلیل موسیقی، با امیدی که جهان مدرن می‌توانست خردی که از دست داده بود را بازیابد، به پایان رسید."),
            StoryParagraph("For the Dionysian was the key, was the missing piece, was the wisdom that had been forgotten, and only by recovering it could the modern world be saved from its own shallow optimism.", "زیرا دیونیزوسی کلید بود، قطعه گمشده بود، خردی بود که فراموش شده بود، و تنها با بازیافتنش می‌شد جهان مدرن را از خوش‌بینی سطحی خودش نجات داد."),
            StoryParagraph("And so the third part ended, and the fourth began, with the description of tragedy itself, with the analysis of the tragic art, with the understanding of the marriage that gave birth to the greatest form of art.", "و اینگونه بخش سوم پایان یافت و چهارم آغاز شد، با توصیف خود تراژدی، با تحلیل هنر تراژیک، با فهم ازدواجی که بزرگ‌ترین شکل هنر را زاد."),
            StoryParagraph("For tragedy was the child of the two gods, was the union of the two forces, was the art that held both the Apollonian and the Dionysian in perfect balance, was the art that Nietzsche believed was the highest achievement of the human spirit.", "زیرا تراژدی فرزند دو خدا بود، اتحاد دو نیرو بود، هنری بود که هم آپولونی و هم دیونیزوسی را در تعادل کامل نگه می‌داشت، هنری بود که نیچه باور داشت والاترین دستاورد روح انسانی است."),
            StoryParagraph("And so the story continued, as stories must, toward the description of tragedy, toward the analysis of the art that would save humanity from despair, toward the wisdom that Nietzsche sought to teach.", "و اینگونه داستان ادامه یافت، همان‌طور که داستان‌ها باید، به سمت توصیف تراژدی، به سمت تحلیل هنری که بشریت را از ناامیدی نجات می‌داد، به سمت خردی که نیچه در پی آموختنش بود."),
            StoryParagraph("And so ended the third part of the story of the birth of tragedy, with the Dionysian described, with the music analyzed, with the marriage of the two gods about to give birth to tragedy itself.", "و اینگونه بخش سوم داستان تولد تراژدی با دیونیزوسی توصیف شده، با موسیقی تحلیل شده، با ازدواج دو خدا در شرف زادن خود تراژدی، به پایان رسید."),
            StoryParagraph("The music played, the dance whirled, the wine flowed, the self dissolved, and in the dissolution, in the dance, in the music, tragedy was born.", "موسیقی نواخت، رقص چرخید، شراب جاری شد، خود حل شد، و در حل شدن، در رقص، در موسیقی، تراژدی زاده شد."),
            StoryParagraph("And the tragedy was beautiful, was terrible, was true, was everything that the modern world had forgotten, was everything that Nietzsche sought to recover, was everything that would make life worth living again.", "و تراژدی زیبا بود، هولناک بود، حقیقی بود، هر چیزی بود که جهان مدرن فراموش کرده بود، هر چیزی بود که نیچه در پی بازیافتنش بود، هر چیزی بود که زندگی را دوباره ارزش زیستن می‌کرد."),
            StoryParagraph("And so the third part of the story ended, and the fourth part began, with the birth of tragedy itself, with the art that was the marriage of the two gods, with the wisdom that would save humanity.", "و اینگونه بخش سوم داستان پایان یافت و بخش چهارم آغاز شد، با تولد خود تراژدی، با هنری که ازدواج دو خدا بود، با خردی که بشریت را نجات می‌داد."),
            StoryParagraph("For tragedy was the child of Apollo and Dionysus, was the union of dream and music, was the marriage of form and chaos, was the art that held both truth and beauty in perfect balance.", "زیرا تراژدی فرزند آپولون و دیونیزوس بود، اتحاد رؤیا و موسیقی بود، ازدواج شکل و آشوب بود، هنری بود که هم حقیقت و هم زیبایی را در تعادل کامل نگه می‌داشت."),
            StoryParagraph("And so ended the third part of the story of the birth of tragedy, with everything in place for the birth, with everything ready for the marriage, with everything building toward the moment when tragedy would be born.", "و اینگونه بخش سوم داستان تولد تراژدی با همه چیز آماده برای تولد، با همه چیز مهیا برای ازدواج، با همه چیز در حال ساختن به سمت لحظه‌ای که تراژدی زاده می‌شد، به پایان رسید."),
            StoryParagraph("The two gods stood together, the god of the dream and the god of the music, and between them, in the space they created together, tragedy was being born, and the birth would change everything.", "دو خدا با هم ایستادند، خدای رؤیا و خدای موسیقی، و میان آن‌ها، در فضایی که با هم آفریدند، تراژدی زاده می‌شد، و تولد همه چیز را تغییر می‌داد.")
        )
    )

    private fun chapter4() = StoryChapter(
        number = 4, title = "The Birth of Tragedy", titlePersian = "تولد تراژدی",
        paragraphs = listOf(
            StoryParagraph("And so tragedy was born, born from the marriage of the two gods, born from the union of dream and music, born from the meeting of Apollo and Dionysus, born from the marriage of form and chaos.", "و اینگونه تراژدی زاده شد، از ازدواج دو خدا زاده شد، از اتحاد رؤیا و موسیقی زاده شد، از ملاقات آپولون و دیونیزوس زاده شد، از ازدواج شکل و آشوب زاده شد."),
            StoryParagraph("Tragedy was born in Greece, born in Athens, born in the theater of Dionysus, born on a stage where actors performed before an audience that came to see and to feel and to be transformed.", "تراژدی در یونان زاده شد، در آتن زاده شد، در تئاتر دیونیزوس زاده شد، روی صحنه‌ای که بازیگران اجرا می‌کردند در برابر تماشاگرانی که آمده بودند تا ببینند و حس کنند و دگرگون شوند."),
            StoryParagraph("And what was this tragedy, this art that was born from the marriage of the two gods? It was a play, yes, a story, yes, a performance, yes, but it was also something more, something that cannot be reduced to any of these things.", "و این تراژدی چه بود، این هنری که از ازدواج دو خدا زاده شد؟ نمایشی بود، آری، داستانی بود، آری، اجرایی بود، آری، اما چیزی بیشتر هم بود، چیزی که نمی‌شود به هیچ‌کدام از این‌ها تقلیل داد."),
            StoryParagraph("Tragedy was the representation of human suffering, of human greatness, of human failure, of human triumph, of everything that makes us human, everything that makes us suffer, everything that makes us beautiful.", "تراژدی نمایندگی رنج انسانی بود، عظمت انسانی، شکست انسانی، پیروزی انسانی، هر چیزی که ما را انسان می‌کند، هر چیزی که ما را رنج می‌دهد، هر چیزی که ما را زیبا می‌کند."),
            StoryParagraph("The tragic hero was a great man, a king, a prince, a hero, a man of noble birth and noble character, a man who stood above the ordinary crowd, a man who was destined for greatness and for destruction.", "قهرمان تراژیک مردی بزرگ بود، پادشاهی، شاهزاده‌ای، قهرمانی، مردی با اصالت نجیب و شخصیت نجیب، مردی که بالاتر از جمع معمولی ایستاده بود، مردی که برای عظمت و نابودی مقدر شده بود."),
            StoryParagraph("And yet, despite his greatness, or perhaps because of it, the tragic hero suffered, suffered terribly, suffered without end, suffered in ways that no ordinary man could bear, suffered in ways that only a hero could bear.", "و با این حال، علی‌رغم عظمتش، یا شاید به خاطر آن، قهرمان تراژیک رنج می‌کشید، هولناک رنج می‌کشید، بی‌پایان رنج می‌کشید، به شیوه‌هایی که هیچ مرد معمولی نمی‌توانست تحمل کند، به شیوه‌هایی که تنها یک قهرمان می‌توانست تحمل کند."),
            StoryParagraph("For the tragic hero was not an ordinary man, was not a victim, was not a mere sufferer, but a man who chose his suffering, who chose his fate, who chose to walk the path that led to his destruction.", "زیرا قهرمان تراژیک مردی معمولی نبود، قربانی نبود، تنها رنج‌کش نبود، بلکه مردی بود که رنجش را انتخاب کرد، سرنوشتش را انتخاب کرد، انتخاب کرد راهی را که به نابودی‌اش می‌رسید بپیماید."),
            StoryParagraph("And this choice, this free choice, this conscious decision to walk the path of suffering, was what made the tragic hero great, was what made him beautiful, was what made him worthy of our admiration and our tears.", "و این انتخاب، این انتخاب آزاد، این تصمیم آگاهانه برای پیمودن راه رنج، همان چیزی بود که قهرمان تراژیک را بزرگ می‌کرد، زیبا می‌کرد، شایسته تحسین و اشک ما می‌کرد."),
            StoryParagraph("The tragic hero faced his fate with courage, faced his suffering with dignity, faced his destruction with acceptance, and in doing so, he became something more than human, became a symbol of the human spirit at its highest.", "قهرمان تراژیک با شجاعت با سرنوشتش روبرو شد، با کرامت با رنجش روبرو شد، با پذیرش با نابودی‌اش روبرو شد، و در این کار، به چیزی بیشتر از انسان تبدیل شد، به نمادی از روح انسانی در والاترین حدش شد."),
            StoryParagraph("And the audience, watching this, watching the hero suffer and yet not break, watching the hero die and yet not be defeated, watching the hero lose everything and yet remain great, the audience was transformed.", "و تماشاگران، با تماشای این، تماشای رنج کشیدن قهرمان و نشکستن، تماشای مرگ قهرمان و شکست نخوردن، تماشای از دست دادن همه چیز قهرمان و با این حال بزرگ ماندن، تماشاگران دگرگون می‌شدند."),
            StoryParagraph("For in the suffering of the hero, they saw their own suffering. In the death of the hero, they saw their own death. In the greatness of the hero, they saw their own potential for greatness.", "زیرا در رنج قهرمان، رنج خودشان را می‌دیدند. در مرگ قهرمان، مرگ خودشان را می‌دیدند. در عظمت قهرمان، پتانسیل خودشان برای عظمت را می‌دیدند."),
            StoryParagraph("And in the moment of the hero's destruction, they experienced something that they could not experience in ordinary life, experienced a moment of pure being, a moment of complete unity with the whole, a moment of Dionysian ecstasy.", "و در لحظه نابودی قهرمان، چیزی را تجربه می‌کردند که نمی‌توانستند در زندگی معمولی تجربه کنند، لحظه‌ای از هستی ناب، لحظه‌ای از یگانگی کامل با کل، لحظه‌ای از سرخوشی دیونیزوسی تجربه می‌کردند."),
            StoryParagraph("This was the power of tragedy, this was the wisdom of tragedy, this was the gift of tragedy to the human race: the ability to face the truth of existence and yet to affirm life, the ability to see the terror and yet to say yes.", "این قدرت تراژدی بود، این خرد تراژدی بود، این هدیه تراژدی به نژاد انسانی بود: توانایی رویارویی با حقیقت هستی و با این حال تأیید زندگی، توانایی دیدن وحشت و با این حال گفتن آری."),
            StoryParagraph("For this was not pessimism, this was not resignation, this was not despair. This was the highest form of optimism, the only honest form of optimism, the only optimism that could survive contact with reality.", "زیرا این بدبینی نبود، این تسلیم نبود، این ناامیدی نبود. این والاترین شکل خوش‌بینی بود، تنها شکل صادقانه خوش‌بینی، تنها خوش‌بینی‌ای که می‌توانست با واقعیت تماس پیدا کند و جان به سلامت ببرد."),
            StoryParagraph("The Greeks, Nietzsche said, were not pessimists. They were not weary of life, not tired of existence, not eager for death. They loved life, loved it passionately, loved it so much that they could bear to see it as it really was.", "یونانیان، نیچه گفت، بدبین نبودند. از زندگی خسته نبودند، از هستی خسته نبودند، مشتاق مرگ نبودند. زندگی را دوست داشتند، پرشور دوستش داشتند، آنقدر دوستش داشتند که می‌توانستند تحمل کنند آن را همان‌طور که واقعاً بود ببینند."),
            StoryParagraph("And what they saw was terrible, was painful, was unbearable, was everything that the modern world tries to hide, tries to deny, tries to forget. And yet, having seen it, they said yes.", "و آنچه دیدند هولناک بود، دردناک بود، غیرقابل تحمل بود، هر چیزی بود که جهان مدرن تلاش می‌کند پنهانش کند، انکارش کند، فراموشش کند. و با این حال، پس از دیدنش، آری گفتند."),
            StoryParagraph("They said yes to life, to suffering, to death, to everything that makes existence what it is. They said yes to the whole, to the totality, to the terrible beauty of the world as it is, without illusion, without pretense, without hope.", "به زندگی آری گفتند، به رنج، به مرگ، به هر چیزی که هستی را آنچه هست می‌کند. به کل آری گفتند، به تمامیت، به زیبایی هولناک جهان همان‌طور که هست، بدون توهم، بدون تظاهر، بدون امید."),
            StoryParagraph("And this yes, this affirmation, this tragic wisdom, was the highest achievement of the human spirit, was the greatest gift that the Greeks gave to the world, was the wisdom that Nietzsche sought to recover for the modern age.", "و این آری، این تأیید، این خرد تراژیک، والاترین دستاورد روح انسانی بود، بزرگ‌ترین هدیه‌ای که یونانیان به جهان دادند، خردی بود که نیچه در پی بازیافتنش برای عصر مدرن بود."),
            StoryParagraph("For the modern world had forgotten this wisdom, had replaced it with shallow optimism, had taught itself to look away from suffering, to deny death, to pretend that everything was fine, to lie to itself about the nature of reality.", "زیرا جهان مدرن این خرد را فراموش کرده بود، با خوش‌بینی سطحی جایگزینش کرده بود، به خودش یاد داده بود از رنج روی برگرداند، مرگ را انکار کند، تظاهر کند همه چیز خوب است، به خودش درباره ماهیت واقعیت دروغ بگوید."),
            StoryParagraph("And this lie, Nietzsche said, was destroying the modern world, was making it weak, was making it unable to face the challenges of existence, was making it unable to live fully, unable to live honestly, unable to live at all.", "و این دروغ، نیچه گفت، جهان مدرن را نابود می‌کرد، ضعیفش می‌کرد، ناتوانش از رویارویی با چالش‌های هستی می‌کرد، ناتوانش از زندگی کردن به تمامی، از صادقانه زندگی کردن، از اصلاً زندگی کردن می‌کرد."),
            StoryParagraph("And so Nietzsche called for a return to tragedy, called for a return to the wisdom of the Greeks, called for a return to the art that could face the truth and still affirm life, called for a return to the wisdom that could save humanity.", "و اینگونه نیچه خواستار بازگشت به تراژدی شد، خواستار بازگشت به خرد یونانیان شد، خواستار بازگشت به هنری شد که می‌توانست با حقیقت روبرو شود و با این حال زندگی را تأیید کند، خواستار بازگشت به خردی شد که می‌توانست بشریت را نجات دهد."),
            StoryParagraph("And so ended the fourth part of the story of the birth of tragedy, with the description of the tragic art, with the analysis of the tragic hero, with the understanding of the wisdom that the Greeks had achieved and that the modern world had lost.", "و اینگونه بخش چهارم داستان تولد تراژدی با توصیف هنر تراژیک، با تحلیل قهرمان تراژیک، با فهم خردی که یونانیان به دست آورده بودند و جهان مدرن از دست داده بود، به پایان رسید."),
            StoryParagraph("For tragedy was not merely an art form, not merely a literary genre, not merely a cultural artifact, but a way of being, a way of facing, a way of affirming, a way of living that could survive contact with the truth.", "زیرا تراژدی تنها یک شکل هنری نبود، تنها یک ژانر ادبی نبود، تنها یک اثر فرهنگی نبود، بلکه شیوه‌ای از بودن بود، شیوه‌ای از رویارویی، شیوه‌ای از تأیید، شیوه‌ای از زندگی که می‌توانست با حقیقت تماس پیدا کند و جان به سلامت ببرد."),
            StoryParagraph("And so the fourth part ended, and the fifth began, with the critique of the modern world, with the analysis of the shallow optimism that had replaced the tragic wisdom, with the call for a new art that could save humanity.", "و اینگونه بخش چهارم پایان یافت و پنجم آغاز شد، با نقد جهان مدرن، با تحلیل خوش‌بینی سطحی که جایگزین خرد تراژیک شده بود، با دعوت به هنری نو که می‌توانست بشریت را نجات دهد."),
            StoryParagraph("For the modern world had lost its way, had forgotten its wisdom, had replaced the tragic with the optimistic, had replaced the profound with the shallow, had replaced the real with the beautiful illusion.", "زیرا جهان مدرن راهش را گم کرده بود، خردش را فراموش کرده بود، تراژیک را با خوش‌بینانه جایگزین کرده بود، عمیق را با سطحی، واقعی را با توهم زیبا."),
            StoryParagraph("And so the story continued, as stories must, toward the critique of the modern world, toward the call for the recovery of the tragic, toward the hope that humanity could once again learn to face the truth and say yes to life.", "و اینگونه داستان ادامه یافت، همان‌طور که داستان‌ها باید، به سمت نقد جهان مدرن، به سمت دعوت به بازیافتن تراژیک، به سمت امیدی که بشریت می‌توانست دوباره یاد بگیرد با حقیقت روبرو شود و به زندگی آری بگوید."),
            StoryParagraph("And so ended the fourth part of the story of the birth of tragedy, with the tragic wisdom described, with the tragic hero analyzed, with the tragedy that would save humanity finally understood.", "و اینگونه بخش چهارم داستان تولد تراژدی با خرد تراژیک توصیف شده، با قهرمان تراژیک تحلیل شده، با تراژدی‌ای که بشریت را نجات می‌داد بالاخره فهمیده شده، به پایان رسید."),
            StoryParagraph("The theater was full, the audience was silent, the actors performed, and on the stage, in the story, in the suffering, the audience saw the truth of their own existence, and having seen it, they did not despair, but were transformed.", "تئاتر پر بود، تماشاگران ساکت بودند، بازیگران اجرا می‌کردند، و روی صحنه، در داستان، در رنج، تماشاگران حقیقت هستی خودشان را دیدند، و پس از دیدنش، ناامید نشدند بلکه دگرگون شدند."),
            StoryParagraph("And so the fourth part ended, and the fifth began, and the story moved toward the critique of the modern world, and the critique would be severe, and nothing could soften it.", "و اینگونه بخش چهارم پایان یافت و پنجم آغاز شد و داستان به سمت نقد جهان مدرن حرکت کرد و نقد شدید می‌بود و هیچ چیز نمی‌توانست تلطیفش کند."),
            StoryParagraph("For Nietzsche had seen what the modern world was doing to itself, had seen the lie that it was telling, had seen the despair that it was hiding, and he would not be silent, could not be silent, would not rest until he had spoken the truth.", "زیرا نیچه دیده بود جهان مدرن با خودش چه می‌کند، دروغی که به خودش می‌گوید را دیده بود، ناامیدی‌ای که پنهان می‌کند را دیده بود، و ساکت نمی‌ماند، نمی‌توانست ساکت بماند، آرام نمی‌گرفت تا حقیقت را گفته بود.")
        )
    )

    private fun chapter5() = StoryChapter(
        number = 5, title = "The Critique of Modernity", titlePersian = "نقد مدرنیته",
        paragraphs = listOf(
            StoryParagraph("The modern world, Nietzsche said, has lost its way, has forgotten the wisdom of the ancients, has replaced the tragic with the optimistic, has replaced the profound with the shallow, has replaced the real with the comfortable.", "جهان مدرن، نیچه گفت، راهش را گم کرده، خرد گذشتگان را فراموش کرده، تراژیک را با خوش‌بینانه جایگزین کرده، عمیق را با سطحی، واقعی را با راحت."),
            StoryParagraph("The modern world believes in progress, believes that things are getting better, believes that science and reason and technology will solve all problems, believes that suffering can be eliminated, believes that happiness can be achieved.", "جهان مدرن به پیشرفت باور دارد، باور دارد چیزها دارند بهتر می‌شوند، باور دارد علم و عقل و فناوری همه مشکلات را حل می‌کنند، باور دارد رنج می‌تواند حذف شود، باور دارد خوشبختی می‌تواند به دست آید."),
            StoryParagraph("But this belief, Nietzsche said, is a lie, is a shallow lie, is a lie that ignores the fundamental facts of existence, is a lie that will eventually be exposed, is a lie that will eventually destroy those who believe it.", "اما این باور، نیچه گفت، دروغ است، دروغی سطحی است، دروغی است که حقایق بنیادی هستی را نادیده می‌گیرد، دروغی است که در نهایت آشکار می‌شود، دروغی است که در نهایت باورکنندگانش را نابود می‌کند."),
            StoryParagraph("For suffering is not a problem to be solved, is not a disease to be cured, is not a defect to be corrected. Suffering is part of existence, is inseparable from life, is the price we pay for being alive.", "زیرا رنج مسئله‌ای نیست که حل شود، بیماری‌ای نیست که درمان شود، نقصی نیست که تصحیح شود. رنج بخشی از هستی است، جدانشدنی از زندگی، بهایی است که برای زنده بودن می‌پردازیم."),
            StoryParagraph("To pretend that suffering can be eliminated is to pretend that life can be eliminated, is to pretend that existence can be escaped, is to pretend that we can become something other than what we are.", "تظاهر به اینکه رنج می‌تواند حذف شود یعنی تظاهر به اینکه زندگی می‌تواند حذف شود، یعنی تظاهر به اینکه هستی می‌تواند از آن گریخت، یعنی تظاهر به اینکه می‌توانیم چیزی جز آنچه هستیم شویم."),
            StoryParagraph("And the modern world does pretend these things, does live in this illusion, does build its entire civilization on this lie, does teach its children this falsehood, does punish those who dare to speak the truth.", "و جهان مدرن این چیزها را تظاهر می‌کند، در این توهم زندگی می‌کند، تمام تمدنش را بر این دروغ بنا می‌کند، به فرزندانش این دروغ را می‌آموزد، کسانی که جرات گفتن حقیقت را دارند مجازات می‌کند."),
            StoryParagraph("And so the modern world is weak, is fragile, is unable to face reality, is unable to bear the truth, is unable to live fully, is unable to die well, is unable to do anything that requires courage or depth or authenticity.", "و اینگونه جهان مدرن ضعیف است، شکننده است، ناتوان از رویارویی با واقعیت است، ناتوان از تحمل حقیقت است، ناتوان از زندگی کردن به تمامی، ناتوان از خوب مردن، ناتوان از هر کاری که به شجاعت یا عمق یا اصالت نیاز دارد."),
            StoryParagraph("The modern world has replaced tragedy with melodrama, has replaced the profound with the sentimental, has replaced the beautiful with the pretty, has replaced the sublime with the merely pleasant.", "جهان مدرن تراژدی را با ملودرام جایگزین کرده، عمیق را با احساساتی، زیبا را با قشنگ، والا را با صرفاً خوشایند."),
            StoryParagraph("The modern world cannot bear to look at suffering, cannot bear to face death, cannot bear to admit that life is anything other than pleasant. And so it looks away, and so it lies, and so it dies a little more each day.", "جهان مدرن نمی‌تواند تحمل کند به رنج نگاه کند، نمی‌تواند تحمل کند با مرگ روبرو شود، نمی‌تواند تحمل کند بپذیرد زندگی هر چیزی جز خوشایند است. و اینگونه روی می‌گرداند، و اینگونه دروغ می‌گوید، و اینگونه هر روز کمی بیشتر می‌میرد."),
            StoryParagraph("And this, Nietzsche said, is the true sickness of the modern age, is the true source of its despair, is the true reason for its emptiness, is the true cause of its inability to live.", "و این، نیچه گفت، بیماری واقعی عصر مدرن است، منبع واقعی ناامیدی‌اش است، دلیل واقعی پوچی‌اش است، علت واقعی ناتوانی‌اش از زندگی است."),
            StoryParagraph("For how can one live who cannot face death? How can one be happy who cannot bear sorrow? How can one be whole who has denied a part of oneself? How can one be human who has rejected the tragic nature of existence?", "زیرا چگونه می‌تواند کسی زندگی کند که نمی‌تواند با مرگ روبرو شود؟ چگونه می‌تواند کسی خوشحال باشد که نمی‌تواند اندوه را تحمل کند؟ چگونه می‌تواند کسی کامل باشد که بخشی از خودش را انکار کرده؟ چگونه می‌تواند کسی انسان باشد که ماهیت تراژیک هستی را رد کرده؟"),
            StoryParagraph("And so Nietzsche called for a return to the tragic, called for a return to the wisdom of the Greeks, called for a return to the art that could face the truth and still affirm life, called for a return to the courage that the modern world had lost.", "و اینگونه نیچه خواستار بازگشت به تراژیک شد، خواستار بازگشت به خرد یونانیان شد، خواستار بازگشت به هنری شد که می‌توانست با حقیقت روبرو شود و با این حال زندگی را تأیید کند، خواستار بازگشت به شجاعتی شد که جهان مدرن از دست داده بود."),
            StoryParagraph("And this return, he said, would not be easy, would require a revolution in thought, would require a revolution in art, would require a revolution in life itself. But it was necessary, was absolutely necessary, was the only way to save humanity.", "و این بازگشت، او گفت، آسان نمی‌بود، به انقلابی در اندیشه نیاز داشت، به انقلابی در هنر، به انقلابی در خود زندگی. اما لازم بود، مطلقاً لازم بود، تنها راه نجات بشریت بود."),
            StoryParagraph("For humanity was dying, was dying of its own shallow optimism, was dying of its own comfortable lies, was dying of its own refusal to face the truth. And only a return to the tragic could save it, could bring it back to life, could teach it how to live.", "زیرا بشریت داشت می‌مرد، از خوش‌بینی سطحی خودش می‌مرد، از دروغ‌های راحتش می‌مرد، از امتناعش از رویارویی با حقیقت می‌مرد. و تنها بازگشتی به تراژیک می‌توانست نجاتش دهد، به زندگی بازگرداندش، به او بیاموزد چطور زندگی کند."),
            StoryParagraph("And so Nietzsche called for a new tragedy, called for a new art, called for a new wisdom that would be the old wisdom reborn in a new form, would be the old truth spoken in a new language, would be the old courage renewed for a new age.", "و اینگونه نیچه خواستار تراژدی نوینی شد، خواستار هنر نوینی شد، خواستار خرد نوینی شد که خرد کهن در شکلی نو باززاده شده باشد، حقیقت کهن به زبانی نو گفته شده باشد، شجاعت کهن برای عصری نو بازآفریده شده باشد."),
            StoryParagraph("And this new tragedy, he said, would come from music, would come from the Dionysian, would come from the ecstasy that the modern world had forgotten, would come from the depths that the modern world had denied.", "و این تراژدی نوین، او گفت، از موسیقی می‌آمد، از دیونیزوسی می‌آمد، از سرخوشی‌ای که جهان مدرن فراموش کرده بود می‌آمد، از عمق‌هایی که جهان مدرن انکار کرده بود می‌آمد."),
            StoryParagraph("And in this new tragedy, in this new art, in this new wisdom, humanity would find itself again, would find its courage again, would find its truth again, would find its life again, would find everything that the modern world had taken from it.", "و در این تراژدی نوین، در این هنر نوین، در این خرد نوین، بشریت خودش را دوباره می‌یافت، شجاعتش را دوباره می‌یافت، حقیقتش را دوباره می‌یافت، زندگی‌اش را دوباره می‌یافت، هر چیزی که جهان مدرن از او گرفته بود را دوباره می‌یافت."),
            StoryParagraph("And so ended the fifth part of the story of the birth of tragedy, with the critique of the modern world, with the analysis of the shallow optimism that had replaced the tragic wisdom, with the call for a new art that could save humanity.", "و اینگونه بخش پنجم داستان تولد تراژدی با نقد جهان مدرن، با تحلیل خوش‌بینی سطحی که جایگزین خرد تراژیک شده بود، با دعوت به هنری نو که می‌توانست بشریت را نجات دهد، به پایان رسید."),
            StoryParagraph("For the modern world was not merely wrong, was not merely foolish, was not merely shallow, but was dying, was destroying itself, was committing a slow suicide of the spirit.", "زیرا جهان مدرن تنها اشتباه نمی‌کرد، تنها احمق نبود، تنها سطحی نبود، بلکه داشت می‌مرد، خودش را نابود می‌کرد، خودکشی آهسته‌ای از روح مرتکب می‌شد."),
            StoryParagraph("And so the fifth part ended, and the sixth began, with the hope of recovery, with the promise of a new tragedy, with the belief that humanity could once again learn to face the truth and say yes to life.", "و اینگونه بخش پنجم پایان یافت و ششم آغاز شد، با امید بهبودی، با وعده تراژدی نوین، با باور به اینکه بشریت می‌توانست دوباره یاد بگیرد با حقیقت روبرو شود و به زندگی آری بگوید."),
            StoryParagraph("For Nietzsche was not a pessimist, was not a nihilist, was not a cynic. Nietzsche was a prophet of hope, was a prophet of courage, was a prophet of the tragic affirmation that could save humanity from its own despair.", "زیرا نیچه بدبین نبود، نیست‌انگار نبود، بدخواه نبود. نیچه پیامبر امید بود، پیامبر شجاعت، پیامبر تأیید تراژیکی که می‌توانست بشریت را از ناامیدی خودش نجات دهد."),
            StoryParagraph("And so the story continued, as stories must, toward the hope of recovery, toward the promise of a new tragedy, toward the belief that humanity could once again become what it was meant to be.", "و اینگونه داستان ادامه یافت، همان‌طور که داستان‌ها باید، به سمت امید بهبودی، به سمت وعده تراژدی نوین، به سمت باور به اینکه بشریت می‌توانست دوباره آنچه قرار بود باشد شود."),
            StoryParagraph("And so ended the fifth part of the story of the birth of tragedy, with the modern world critiqued, with the shallow optimism exposed, with the tragic wisdom that had been lost and that could be recovered finally understood.", "و اینگونه بخش پنجم داستان تولد تراژدی با جهان مدرن نقد شده، با خوش‌بینی سطحی آشکار شده، با خرد تراژیکی که از دست رفته بود و می‌توانست بازیافته شود بالاخره فهمیده شده، به پایان رسید."),
            StoryParagraph("The critique was severe, was merciless, was devastating, and yet it was also hopeful, for it pointed the way to a recovery, to a rebirth, to a new life that could be lived in full awareness of the tragic nature of existence.", "نقد شدید بود، بی‌رحم بود، ویرانگر بود، و با این حال امیدوارکننده هم بود، زیرا راه را به سمت بهبودی نشان می‌داد، به سمت تولد دوباره، به سمت زندگی نوینی که می‌شد در آگاهی کامل از ماهیت تراژیک هستی زندگی کرد."),
            StoryParagraph("And so the fifth part ended, and the sixth began, and the story moved toward the hope of recovery, and the hope would be expressed in the most beautiful way, in the most profound way, in the most human way.", "و اینگونه بخش پنجم پایان یافت و ششم آغاز شد و داستان به سمت امید بهبودی حرکت کرد و امید به زیباترین شیوه بیان می‌شد، به عمیق‌ترین شیوه، به انسانی‌ترین شیوه."),
            StoryParagraph("And so ended the fifth part of the story of the birth of tragedy, with the modern world judged, with the shallow optimism condemned, with the tragic wisdom that could save humanity finally revealed.", "و اینگونه بخش پنجم داستان تولد تراژدی با جهان مدرن داوری شده، با خوش‌بینی سطحی محکوم شده، با خرد تراژیکی که می‌توانست بشریت را نجات دهد بالاخره آشکار شده، به پایان رسید."),
            StoryParagraph("The judge had spoken, the verdict had been given, the sentence had been passed, and now there was only the question of whether humanity would listen, would heed, would change, would be saved.", "قاضی سخن گفته بود، حکم داده شده بود، مجازات صادر شده بود، و اکنون تنها این پرسش بود که آیا بشریت گوش می‌دهد، توجه می‌کند، تغییر می‌کند، نجات می‌یابد."),
            StoryParagraph("And so the fifth part of the story of the birth of tragedy ended, with the critique complete, with the hope expressed, with the sixth part about to begin.", "و اینگونه بخش پنجم داستان تولد تراژدی با نقد کامل، با امید بیان شده، با بخش ششم در شرف آغاز، به پایان رسید.")
        )
    )

    private fun chapter6() = StoryChapter(
        number = 6, title = "The Rebirth of Tragedy", titlePersian = "تولد دوباره تراژدی",
        paragraphs = listOf(
            StoryParagraph("And so we come to the end, to the hope, to the promise, to the belief that tragedy can be reborn, can be recovered, can save humanity from the despair into which it has fallen.", "و اینگونه به پایان می‌رسیم، به امید، به وعده، به باور به اینکه تراژدی می‌تواند دوباره زاده شود، بازیافته شود، بشریت را از ناامیدی‌ای که در آن افتاده نجات دهد."),
            StoryParagraph("For Nietzsche did not end his book in despair, did not end it in resignation, did not end it in cynicism. He ended it in hope, in promise, in the belief that the future could be better than the present.", "زیرا نیچه کتابش را در ناامیدی تمام نکرد، در تسلیم تمام نکرد، در بدبینی تمام نکرد. آن را در امید تمام کرد، در وعده، در باور به اینکه آینده می‌تواند بهتر از حال باشد."),
            StoryParagraph("And this hope, this promise, this belief, was not based on the shallow optimism that he had criticized, was not based on the comfortable lies that he had condemned, was not based on the denial of reality that he had rejected.", "و این امید، این وعده، این باور، بر خوش‌بینی سطحی‌ای که نقدش کرده بود بنا نشده بود، بر دروغ‌های راحتی که محکومشان کرده بود بنا نشده بود، بر انکار واقعیتی که ردش کرده بود بنا نشده بود."),
            StoryParagraph("It was based on tragedy, on the tragic wisdom, on the art that could face the truth and still affirm life. It was based on the marriage of the two gods, on the union of dream and music, on the meeting of Apollo and Dionysus.", "بر تراژدی بنا شده بود، بر خرد تراژیک، بر هنری که می‌توانست با حقیقت روبرو شود و با این حال زندگی را تأیید کند. بر ازدواج دو خدا بنا شده بود، بر اتحاد رؤیا و موسیقی، بر ملاقات آپولون و دیونیزوس."),
            StoryParagraph("And this marriage, this union, this meeting, was still possible, was still available, was still within the reach of any human being who had the courage to face the truth and the wisdom to affirm life.", "و این ازدواج، این اتحاد، این ملاقات، هنوز ممکن بود، هنوز در دسترس بود، هنوز در محدوده دسترسی هر انسانی بود که جرات رویارویی با حقیقت و خرد تأیید زندگی را داشت."),
            StoryParagraph("For tragedy was not dead, was not gone, was not lost forever. Tragedy was waiting, was waiting for someone to write it, was waiting for someone to perform it, was waiting for someone to experience it, was waiting for someone to live it.", "زیرا تراژدی مرده نبود، رفته نبود، برای همیشه گم نشده بود. تراژدی منتظر بود، منتظر بود تا کسی بنویسدش، منتظر بود تا کسی اجرایش کند، منتظر بود تا کسی تجربه‌اش کند، منتظر بود تا کسی زندگی‌اش کند."),
            StoryParagraph("And Nietzsche believed that this someone would come, was coming, was already here in the music of Wagner, was already present in the art of the future, was already alive in the spirit of those who had not forgotten the tragic wisdom.", "و نیچه باور داشت این کسی می‌آمد، داشت می‌آمد، قبلاً در موسیقی واگنر اینجا بود، قبلاً در هنر آینده حاضر بود، قبلاً در روح کسانی که خرد تراژیک را فراموش نکرده بودند زنده بود."),
            StoryParagraph("And so Nietzsche ended his book with a call, with a plea, with a prophecy. He called for a new tragedy, pleaded for a new art, prophesied a new age in which humanity would once again learn to face the truth and say yes to life.", "و اینگونه نیچه کتابش را با دعوتی، با التماسی، با پیشگویی‌ای تمام کرد. خواستار تراژدی نوینی شد، برای هنر نوینی التماس کرد، عصر نوینی را پیشگویی کرد که در آن بشریت دوباره یاد می‌گرفت با حقیقت روبرو شود و به زندگی آری بگوید."),
            StoryParagraph("And this new age, he said, would not be an age of comfort, would not be an age of ease, would not be an age of shallow happiness. It would be an age of courage, of depth, of authenticity, of tragic affirmation.", "و این عصر نوین، او گفت، عصر راحتی نمی‌بود، عصر آسانی نمی‌بود، عصر خوشبختی سطحی نمی‌بود. عصر شجاعت می‌بود، عمق، اصالت، تأیید تراژیک."),
            StoryParagraph("It would be an age in which human beings would once again be able to look at the abyss, would be able to face death, would be able to bear suffering, would be able to affirm life in all its terror and all its beauty.", "عصری می‌بود که در آن انسان‌ها دوباره قادر می‌بودند به پرتگاه نگاه کنند، قادر می‌بودند با مرگ روبرو شوند، قادر می‌بودند رنج را تحمل کنند، قادر می‌بودند زندگی را در تمام وحشت و تمام زیبایی‌اش تأیید کنند."),
            StoryParagraph("And in this age, in this new age, in this age that was to come, human beings would be whole again, would be complete again, would be fully human again, would be everything that the modern world had prevented them from being.", "و در این عصر، در این عصر نوین، در این عصری که می‌آمد، انسان‌ها دوباره کامل می‌بودند، دوباره تمام، دوباره کاملاً انسان، دوباره هر چیزی که جهان مدرن مانعشان شده بود باشند."),
            StoryParagraph("And so ended the book, ended the meditation on the birth of tragedy, ended the call for a new art, ended the prophecy of a new age. But the story was not over, was not really over, would never truly be over.", "و اینگونه کتاب تمام شد، تأمل بر تولد تراژدی تمام شد، دعوت به هنر نوین تمام شد، پیشگویی عصر نوین تمام شد. اما داستان تمام نشده بود، واقعاً تمام نشده بود، هرگز واقعاً تمام نمی‌شد."),
            StoryParagraph("For the birth of tragedy was not an event, was not a moment, was not a single act, but a process, an ongoing process, a process that could always be renewed, could always be reborn, could always be recovered.", "زیرا تولد تراژدی یک واقعه نبود، یک لحظه نبود، یک عمل واحد نبود، بلکه فرایندی بود، فرایندی در جریان، فرایندی که همیشه می‌توانست تجدید شود، همیشه می‌توانست دوباره زاده شود، همیشه می‌توانست بازیافته شود."),
            StoryParagraph("And so the story of the birth of tragedy was not really a story, not a narrative with a beginning and a middle and an end, but a cycle, an eternal cycle, an eternal return of the tragic wisdom that humanity must always recover.", "و اینگونه داستان تولد تراژدی واقعاً یک داستان نبود، روایتی با آغاز و میانه و پایان نبود، بلکه چرخه‌ای بود، چرخه‌ای ابدی، بازگشتی ابدی از خرد تراژیکی که بشریت همیشه باید بازیابد."),
            StoryParagraph("For every age must confront the same questions, must face the same terrors, must make the same choices. Every age must decide whether to face the truth or to flee from it, whether to affirm life or to deny it, whether to be tragic or to be shallow.", "زیرا هر عصری باید با همان پرسش‌ها روبرو شود، با همان وحشت‌ها، همان انتخاب‌ها. هر عصری باید تصمیم بگیرد با حقیقت روبرو شود یا از آن بگریزد، زندگی را تأیید کند یا انکارش کند، تراژیک باشد یا سطحی."),
            StoryParagraph("And Nietzsche, in writing the birth of tragedy, in describing the two gods, in analyzing the tragic art, in calling for a new age, was doing what every great philosopher does: he was reminding humanity of what it had forgotten.", "و نیچه، در نوشتن تولد تراژدی، در توصیف دو خدا، در تحلیل هنر تراژیک، در دعوت به عصر نوین، همان کاری را می‌کرد که هر فیلسوف بزرگی می‌کند: بشریت را به یاد آنچه فراموش کرده بود می‌انداخت."),
            StoryParagraph("He was reminding us that life is tragic, that existence is terrible, that suffering is real. And he was reminding us that despite all this, or perhaps because of it, life is worth living, existence is worth affirming, suffering is worth bearing.", "او به ما یادآوری می‌کرد زندگی تراژیک است، هستی هولناک است، رنج واقعی است. و به ما یادآوری می‌کرد که علی‌رغم همه این‌ها، یا شاید به خاطر همه این‌ها، زندگی ارزش زیستن دارد، هستی ارزش تأیید کردن، رنج ارزش تحمل کردن."),
            StoryParagraph("And so ended the story of the birth of tragedy, with the birth described, with the marriage celebrated, with the two gods united, with the wisdom that could save humanity finally understood.", "و اینگونه داستان تولد تراژدی با تولد توصیف شده، با ازدواج جشن گرفته شده، با دو خدا متحد شده، با خردی که می‌توانست بشریت را نجات دهد بالاخره فهمیده شده، به پایان رسید."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("But the story remains, remains to be told again, remains to be lived again, remains to be reborn again, as long as there are human beings who need to hear it.", "اما داستان باقی می‌ماند، باقی می‌ماند تا دوباره گفته شود، باقی می‌ماند تا دوباره زندگی شود، باقی می‌ماند تا دوباره زاده شود، تا زمانی که انسان‌هایی باشند که نیاز دارند بشنوندش."),
            StoryParagraph("And so ended the sixth and final part of the story of the birth of tragedy, with the birth described, with the marriage celebrated, with the two gods united, with the wisdom that could save humanity finally understood.", "و اینگونه بخش ششم و آخرین داستان تولد تراژدی با تولد توصیف شده، با ازدواج جشن گرفته شده، با دو خدا متحد شده، با خردی که می‌توانست بشریت را نجات دهد بالاخره فهمیده شده، به پایان رسید."),
            StoryParagraph("For tragedy was not merely an art form, not merely a philosophy, not merely a way of life, but the highest expression of the human spirit, the greatest achievement of the human mind, the deepest truth of the human heart.", "زیرا تراژدی تنها یک شکل هنری نبود، تنها یک فلسفه نبود، تنها یک شیوه زندگی نبود، بلکه والاترین بیان روح انسانی بود، بزرگ‌ترین دستاورد ذهن انسانی، عمیق‌ترین حقیقت قلب انسانی."),
            StoryParagraph("And this tragedy, this art, this spirit, this achievement, this truth, was what Nietzsche sought to recover, was what he sought to teach, was what he sought to live. And his book, his birth of tragedy, was his attempt to do so, was his gift to humanity, was his contribution to the eternal conversation about what it means to be human.", "و این تراژدی، این هنر، این روح، این دستاورد، این حقیقت، چیزی بود که نیچه در پی بازیافتنش بود، در پی آموختنش، در پی زیستنش. و کتابش، تولد تراژدی، تلاشش برای این کار بود، هدیه‌اش به بشریت، سهمش در گفتگوی ابدی درباره معنای انسان بودن."),
            StoryParagraph("And so ended the story of the birth of tragedy, not with a conclusion but with a beginning, not with an answer but with a question, not with a comfort but with a challenge.", "و اینگونه داستان تولد تراژدی پایان یافت، نه با نتیجه‌گیری بلکه با آغازی، نه با پاسخ بلکه با پرسشی، نه با تسلی بلکه با چالشی."),
            StoryParagraph("The challenge was this: to face the truth of existence and yet to affirm life. To see the terror and yet to say yes. To know the darkness and yet to embrace the light. To be tragic and yet to be joyful. To be human and yet to be more.", "چالش این بود: با حقیقت هستی روبرو شدن و با این حال زندگی را تأیید کردن. دیدن وحشت و با این حال گفتن آری. دانستن تاریکی و با این حال در آغوش گرفتن نور. تراژیک بودن و با این حال شادمان. انسان بودن و با این حال بیشتر."),
            StoryParagraph("The challenge was this: to live as if the two gods were still married, as if the dream and the music were still united, as if Apollo and Dionysus were still dancing together on the stage of human existence.", "چالش این بود: چنان زندگی کردن که گویی دو خدا هنوز ازدواج کرده‌اند، گویی رؤیا و موسیقی هنوز متحدند، گویی آپولون و دیونیزوس هنوز با هم روی صحنه هستی انسانی می‌رقصند."),
            StoryParagraph("And so the story of the birth of tragedy ended, but the tragedy itself would never end, would continue to be born again and again, would continue to save humanity again and again, as long as there were human beings who needed saving.", "و اینگونه داستان تولد تراژدی پایان یافت، اما خود تراژدی هرگز تمام نمی‌شد، بارها و بارها زاده می‌شد، بارها و بارها بشریت را نجات می‌داد، تا زمانی که انسان‌هایی بودند که به نجات نیاز داشتند."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For every ending is a beginning, and every beginning is an ending, and the birth of tragedy, like tragedy itself, was both at once, was neither, was something more.", "زیرا هر پایانی آغازی است و هر آغازی پایانی، و تولد تراژدی، همچون خود تراژدی، همزمان هر دو بود، هیچ‌کدام، چیزی بیشتر."),
            StoryParagraph("And so ended the story of the birth of tragedy, as all great stories end, not with a period but with an ellipsis, not with a conclusion but with a continuation, not with a silence but with a call.", "و اینگونه داستان تولد تراژدی پایان یافت، همان‌طور که همه داستان‌های بزرگ پایان می‌یابند، نه با نقطه بلکه با سه‌نقطه، نه با نتیجه‌گیری بلکه با ادامه، نه با سکوت بلکه با خواندن."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("But the story remains.", "اما داستان باقی می‌ماند.")
        )
    )
}